import {analyze,executive,LEVELS,rank,unique} from './analysis.mjs';
import {aiMessages,composeDraft} from './ai-context.mjs';
import {createPdf,keyEvidence,references,REPORT_MODES} from './report.mjs';
import {reportView} from './report-view.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cls=s=>({'Crítico':'critical','Alto':'high','Medio':'medium','Bajo':'low'}[s]||'neutral');
const pill=s=>`<span class="pill ${cls(s)}">${esc(s)}</span>`;
const author='';
const labels={dashboard:['Vista general','De los eventos a una investigación respaldada por evidencia.'],cases:['Incidentes','Secuencias correlacionadas, criticidad y evidencia de origen.'],logs:['Registros del SIEM','Explora los eventos originales y su vínculo con la investigación.'],report:['Informes de investigación','Informe ejecutivo e informe detallado, con descargas independientes.'],ai:['Asistente IA local','Redacción generativa en tu equipo, sin claves API.']};
const state={analysis:null,book:null,fileName:'',hash:'',route:'dashboard',caseLevel:'',logLevel:'',query:'',onlyLinked:false,page:0,hour:'',aiText:'',aiApproved:false,worker:null,aiReady:false,aiBusy:false,aiStatus:'Modelo sin activar',aiProgress:0,aiDevice:'',aiSelection:'all',author,reportMode:'executive',date:new Date().toLocaleDateString('en-CA')};
function notice(t,error=false){$('#notice').className=error?'error':'';$('#notice').textContent=t;}
function resetAiOutput(){state.aiText='';state.aiApproved=false;}
async function digest(buffer){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(x=>x.toString(16).padStart(2,'0')).join('');}
const required=['Log_ID','Timestamp','Hostname','Event_ID','User','Source_IP','Destination','Log_Source','Event_Description','Process_CommandLine','Result','Severity'];
async function readFile(buffer,name){
 if(buffer.byteLength>30*1024*1024)throw new Error('El archivo supera el límite de 30 MB.');
 const book=XLSX.read(buffer,{type:'array',cellDates:false});
 const sheet=book.SheetNames.find(n=>{const m=XLSX.utils.sheet_to_json(book.Sheets[n],{header:1,range:0,blankrows:true});return required.every(k=>m[0]?.includes(k));});
 if(!sheet)throw new Error(`No se encontró una hoja con los encabezados requeridos: ${required.join(', ')}. No se sustituyeron datos.`);
 state.book=book;state.fileName=name;state.hash=await digest(buffer);resetAiOutput();selectSheet(sheet);
 notice(`Archivo cargado: ${state.analysis.metrics.total} eventos. ${state.analysis.metrics.cases} incidentes probables identificados.`);
}
function selectSheet(name){
 const m=XLSX.utils.sheet_to_json(state.book.Sheets[name],{header:1,defval:'',blankrows:true});
 if(!required.every(k=>m[0]?.includes(k))){notice('La hoja seleccionada no tiene todos los encabezados requeridos.',true);return;}
 const h=m[0];const rows=m.slice(1).map((r,i)=>({...Object.fromEntries(h.map((k,j)=>[k,r[j]??''])),sourceRow:i+2,sourceSheet:name})).filter(r=>required.some(k=>r[k]!==''));
 if(!rows.length){notice('La hoja no contiene eventos.',true);return;}
 for(const r of rows)if(typeof r.Timestamp==='number'){const t=XLSX.SSF.parse_date_code(r.Timestamp);r.Timestamp=`${t.y}-${String(t.m).padStart(2,'0')}-${String(t.d).padStart(2,'0')} ${String(t.H).padStart(2,'0')}:${String(t.M).padStart(2,'0')}:${String(Math.floor(t.S)).padStart(2,'0')}`;}
 state.analysis=analyze(rows,{sheet:name,fileName:state.fileName,sha256:state.hash});state.page=0;state.query='';state.hour='';state.caseLevel='';state.logLevel='';state.onlyLinked=false;resetAiOutput();render();
}
$('#file-input').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{notice('Validando y analizando el archivo…');await readFile(await f.arrayBuffer(),f.name);}catch(e){notice(e.message,true);}e.target.value='';});
document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',async e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(!f)return;if(!/\.xlsx$/i.test(f.name)){notice('Selecciona un archivo .xlsx.',true);return;}try{await readFile(await f.arrayBuffer(),f.name);}catch(e){notice(e.message,true);}});
function source(){const a=state.analysis;$('#source-card').innerHTML=a?`<div class="file-icon">XLSX</div><div><h2>${esc(state.fileName)}</h2><p>${a.metrics.total} eventos · ${esc(a.meta.start)} — ${esc(a.meta.end)} · Zona horaria no especificada</p></div><div class="source-right"><span class="pill low">✓ Analizado</span><select id="sheet-picker" aria-label="Hoja de Excel">${state.book.SheetNames.map(n=>`<option ${n===a.meta.sheet?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`:`<div class="file-icon">XLSX</div><div><h2>Conecta la evidencia de tu investigación</h2><p>Importa el Excel del SIEM. Cada hallazgo conserva su ID y fila de origen.</p></div><div class="source-right"><label class="btn small" for="file-input">Cargar Excel</label></div>`;$('#sheet-picker')?.addEventListener('change',e=>selectSheet(e.target.value));}
function empty(){return `<div class="dropzone" id="dropzone"><div class="eyebrow">COMIENZA UNA INVESTIGACIÓN</div><h2>Tus registros. Una historia por descubrir.</h2><p>Arrastra tu archivo .xlsx aquí para iniciar el análisis.</p><div class="actions"><label class="btn primary" for="file-input">↑ Seleccionar Excel</label></div></div><div class="step-list"><div class="step"><small>01 · IMPORTAR</small><h3>Conserva la evidencia</h3><p>Se mantienen los identificadores y filas originales, con huella SHA-256 del archivo.</p></div><div class="step"><small>02 · INVESTIGAR</small><h3>Conecta los eventos</h3><p>Correlación de accesos, procesos, transferencias, persistencia y actividad web.</p></div><div class="step"><small>03 · DOCUMENTAR</small><h3>Explica lo que ocurrió</h3><p>Revisa los hallazgos, utiliza la IA local y descarga el informe técnico en PDF.</p></div></div>`;}
function caseRows(cases){return cases.map(c=>`<tr class="case-row" data-case="${c.id}" tabindex="0" role="button" aria-label="Abrir ${c.id}"><td><span class="case-title">${esc(c.title)}</span><div class="case-id">${c.id} · ${esc(c.type)}</div></td><td>${pill(c.severity)}</td><td><span class="mono">${esc(c.hosts.slice(0,2).join(', '))}</span>${c.hosts.length>2?`<span class="tiny muted"> +${c.hosts.length-2}</span>`:''}</td><td><span class="mono">${c.start.slice(11)} — ${c.end.slice(11)}</span></td><td><span class="count-badge">${c.evidence.length}</span></td><td class="muted">↗</td></tr>`).join('');}
function dashboard(){const a=state.analysis,m=a.metrics;const counts=LEVELS.map(l=>a.cases.filter(c=>c.severity===l).length);const colors=['#c9344a','#dfa65b','#5788bb','#5c9c83'];let offset=0;const conic=counts.map((n,i)=>{const start=offset;offset+=m.cases?n/m.cases*100:0;return `${colors[i]} ${start}% ${offset}%`;}).join(',');
 const bins=[];const first=a.meta.start.slice(0,13),last=a.meta.end.slice(0,13);if(first&&last){let t=Date.parse(first.replace(' ','T')+':00:00Z'),end=Date.parse(last.replace(' ','T')+':00:00Z');for(;t<=end;t+=3600000){const k=new Date(t).toISOString().slice(0,13).replace('T',' ');const rr=a.rows.filter(r=>String(r.Timestamp).startsWith(k));bins.push({key:k,n:rr.length,s:rr.filter(r=>a.eventCases.has(r._key)).length});}}
 const max=Math.max(1,...bins.map(b=>b.n));
 return `<div class="kpis"><div class="kpi"><div class="kpi-label">Eventos analizados <span>≡</span></div><strong>${m.total.toLocaleString()}</strong><p>Archivo original preservado</p></div><div class="kpi"><div class="kpi-label">Incidentes probables <span>◇</span></div><strong>${m.cases} <span class="small-tag">Por investigar</span></strong><p>Secuencias con evidencia correlacionada</p></div><div class="kpi"><div class="kpi-label">Eventos vinculados <span>↗</span></div><strong>${m.suspicious}</strong><p>${(m.suspicious/m.total*100).toFixed(1)}% del total · ${m.hosts} activos observados</p></div><div class="kpi alert"><div class="kpi-label">Prioridad crítica <span>△</span></div><strong>${m.critical} <span class="pill critical">Atención prioritaria</span></strong><p>${m.high} caso(s) adicional(es) de nivel Alto</p></div></div>
 <div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>Actividad en el tiempo</h2><p>Eventos por hora · selecciona una barra para explorar los registros</p></div><span class="pill neutral">${esc(a.meta.start.slice(0,10))}</span></div><div class="panel-body"><div class="timeline-chart">${bins.map(b=>`<button class="hour-col" data-hour="${b.key}" aria-label="Ver registros ${b.key}, ${b.n} eventos"><span class="tip">${b.key.slice(11)}h · ${b.n} eventos / ${b.s} vinculados</span><span class="bar" style="height:${(b.n-b.s)/max*100}%"></span><span class="bar dark" style="height:${b.s/max*100}%"></span></button>`).join('')}</div><div class="chart-labels">${bins.map(b=>`<span>${b.key.slice(11)}:00</span>`).join('')}</div><div class="legend"><span><i></i>Vinculados a incidentes</span><span><i class="pale"></i>Sin regla coincidente</span></div></div></section>
 <section class="panel"><div class="panel-head"><div><h2>Criticidad de los incidentes</h2><p>Clasificación analítica, con justificación</p></div></div><div class="panel-body"><div class="risk-content"><div class="donut" style="background:${m.cases?`conic-gradient(${conic})`:'#e5e9ed'}"><div><strong>${m.cases}</strong>INCIDENTES</div></div><div class="risk-legend">${LEVELS.map((l,i)=>`<button data-level="${l}" aria-label="Filtrar incidentes ${l}"><span><i style="background:${colors[i]}"></i>${l}</span><strong>${counts[i]}</strong></button>`).join('')}</div></div></div></section></div>
 <section class="panel"><div class="panel-head"><div><h2>Hallazgos de la investigación</h2><p>Abre un caso para examinar la secuencia y sus evidencias</p></div><button class="link" data-action="allcases">Ver todos los casos →</button></div><div class="table-wrap" style="margin-top:17px"><table><thead><tr><th>Hallazgo</th><th>Criticidad</th><th>Activos</th><th>Ventana de tiempo</th><th>Eventos</th><th></th></tr></thead><tbody>${caseRows(a.cases)}</tbody></table></div><div class="table-bottom"><span>${m.cases} incidentes probables · ${m.suspicious} eventos únicos vinculados</span><span>Hoja: ${esc(a.meta.sheet)}</span></div></section>
 <div class="callout"><b>Contexto antes de concluir.</b> ${m.other} registros no coinciden con estas reglas; esto no demuestra que sean benignos. Un evento 4672 indica privilegios de una sesión y requiere más evidencia para afirmar escalamiento.</div>${a.issues.length?`<div class="callout warning">${a.issues.map(esc).join('<br>')}</div>`:''}`;
}
function casesPage(){const a=state.analysis,filtered=a.cases.filter(c=>!state.caseLevel||c.severity===state.caseLevel);return `<section class="panel"><div class="filters"><span class="muted tiny">Filtrar por criticidad</span><select id="case-level" aria-label="Criticidad de incidentes"><option value="">Todos los niveles</option>${LEVELS.map(l=>`<option ${state.caseLevel===l?'selected':''}>${l}</option>`).join('')}</select><span class="muted tiny">${filtered.length} caso(s)</span></div></section><div class="case-grid">${filtered.map(c=>`<article class="case-card"><div style="display:flex;justify-content:space-between"><span class="case-id">${c.id} · ${esc(c.type)}</span>${pill(c.severity)}</div><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><div class="chips">${c.hosts.map(h=>`<span class="pill neutral mono">${esc(h)}</span>`).join('')}</div><div class="actions"><time>${c.start.slice(11)} — ${c.end.slice(11)} · ${c.evidence.length} eventos</time><button class="btn small" data-case="${c.id}">Investigar →</button></div></article>`).join('')||'<div class="empty-state">No hay incidentes con este nivel.</div>'}</div>`;}
function rawTable(rows,detail=false){return `<div class="table-wrap"><table class="evidence"><thead><tr><th>ID / fila</th><th>Fecha / equipo</th><th>Evento / cuenta</th><th>Origen → destino</th><th>Descripción y comando</th><th>Resultado / Severity</th>${detail?'':'<th>Caso</th>'}</tr></thead><tbody>${rows.map(r=>{const cc=state.analysis.eventCases.get(r._key)||[];return `<tr><td><span class="mono">${esc(r.Log_ID)}</span><br><span class="raw-row">${esc(r.sourceSheet)} · fila ${r.sourceRow}</span></td><td class="mono">${esc(r.Timestamp)}<br>${esc(r.Hostname)}</td><td><b>${esc(r.Event_ID)}</b><br><span class="mono">${esc(r.User)}</span></td><td class="mono">${esc(r.Source_IP)||'—'}<br>→ ${esc(r.Destination)||'—'}</td><td class="command">${esc(r.Event_Description)}${r.Process_CommandLine?`<div class="mono" style="margin-top:5px;color:#285f62">${esc(r.Process_CommandLine)}</div>`:''}</td><td>${esc(r.Result)}<br><span class="muted">${esc(r.Severity)}</span></td>${detail?'':`<td>${cc.map(c=>`<button class="link" data-case="${c.id}">${c.id}</button>`).join('')||'<span class="muted">Sin vínculo</span>'}</td>`}</tr>`;}).join('')}</tbody></table></div>`;}
function logsPage(){const a=state.analysis,q=state.query.toLowerCase();const filtered=a.rows.filter(r=>(!q||required.some(k=>String(r[k]).toLowerCase().includes(q)))&&(!state.onlyLinked||a.eventCases.has(r._key))&&(!state.hour||String(r.Timestamp).startsWith(state.hour))&&(!state.logLevel||(a.eventCases.get(r._key)||[]).some(c=>c.severity===state.logLevel)));const size=25,max=Math.max(0,Math.ceil(filtered.length/size)-1);state.page=Math.min(state.page,max);return `<section class="panel"><div class="filters"><input id="log-search" placeholder="Buscar ID, usuario, IP, comando…" aria-label="Buscar registros" value="${esc(state.query)}"><select id="log-level" aria-label="Criticidad analítica"><option value="">Toda criticidad</option>${LEVELS.map(l=>`<option ${state.logLevel===l?'selected':''}>${l}</option>`).join('')}</select><label class="tiny"><input type="checkbox" id="only-linked" ${state.onlyLinked?'checked':''}> Solo vinculados</label><button class="btn small" id="csv">↓ CSV de esta vista</button>${state.hour?`<button class="btn small" id="clear-hour">${state.hour.slice(11)}:00–${Number(state.hour.slice(11))+1}:00 ×</button>`:''}</div><div class="callout" style="margin:0 20px 15px">Se muestran los valores originales. “Severity” es la etiqueta del SIEM; la criticidad analítica pertenece al caso.</div>${filtered.length?rawTable(filtered.slice(state.page*size,(state.page+1)*size)):'<div class="empty-state">No hay registros que coincidan con los filtros.</div>'}<div class="table-bottom"><span>${filtered.length} de ${a.metrics.total} registros · página ${state.page+1} de ${max+1}</span><div class="actions"><button class="btn small" id="prev" ${!state.page?'disabled':''}>← Anterior</button><button class="btn small" id="next" ${state.page>=max?'disabled':''}>Siguiente →</button></div></div></section>`;}
function reportPage(){return reportView(state,esc,pill);}

function aiPage(){const a=state.analysis;return `<div class="ai-shell"><section class="panel ai-panel"><div class="ai-mark">✧</div><h2>Tu asistente de investigación</h2><p>Qwen2.5 trabaja en tu navegador. No necesitas cuenta ni clave API. Los registros permanecen en tu equipo.</p><p class="tiny">La primera descarga es de varios cientos de MB y requiere Internet. La redacción puede tardar en equipos con CPU.</p><button class="btn ${state.aiReady?'':'primary'}" id="load-ai" ${state.aiReady||state.aiBusy?'disabled':''}>${state.aiReady?'✓ Modelo listo':'Activar IA local'}</button><div class="progress"><div id="ai-progress" style="width:${state.aiProgress}%"></div></div><p id="ai-status" class="tiny">${esc(state.aiStatus)}</p><label class="field">Contexto a resumir<select id="ai-context"><option value="all">Resumen de la investigación</option>${a.cases.map(c=>`<option value="${c.id}" ${state.aiSelection===c.id?'selected':''}>${c.id} · ${esc(c.type)}</option>`).join('')}</select></label><button class="btn primary" id="generate-ai" ${!state.aiReady||state.aiBusy?'disabled':''}>✧ Redactar resumen</button>${state.aiBusy?'<button class="btn" id="cancel-ai">Cancelar proceso IA</button>':''}<div class="snapshot">La IA propone qué casos destacar. El resumen usa extractos del análisis verificado y puedes editarlo antes de incluirlo en el PDF.</div></section><section class="panel"><div class="panel-head"><div><h2>Borrador de IA</h2><p>Valida el texto contra las evidencias antes de incluirlo en el PDF.</p></div><span class="pill neutral">${state.aiDevice||'LOCAL'}</span></div><div class="ai-output ${state.aiText?'':'empty'}" id="ai-output">${state.aiText?`<textarea id="ai-edit" class="ai-editor" aria-label="Editar borrador de IA">${esc(state.aiText)}</textarea>`:'<div><div style="font-size:32px;margin-bottom:10px;color:#85b9af">✧</div>Activa el modelo y genera un resumen.<br><span class="tiny">La IA no cambia registros ni añade hallazgos a la investigación.</span></div>'}</div><div class="panel-body"><label class="tiny"><input type="checkbox" id="approve-ai" ${state.aiApproved?'checked':''} ${state.aiText?'':'disabled'}> He revisado el borrador y quiero incluirlo en el informe.</label>${state.aiText?'<button class="btn small" data-action="pdf" style="float:right">Descargar PDF</button>':''}</div></section></div>`;}
function render(){state.route=labels[location.hash.slice(1)]?location.hash.slice(1):'dashboard';const [name,sub]=labels[state.route];$('#section-name').textContent=name;$('#page-title').textContent=name;$('#page-subtitle').textContent=sub;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===state.route));$('#case-count').textContent=state.analysis?.metrics.cases||0;$('#export-top').disabled=!state.analysis;source();$('#content').innerHTML=state.analysis?({dashboard,cases:casesPage,logs:logsPage,report:reportPage,ai:aiPage}[state.route])():empty();bind();}
function navigate(route){location.hash=route;if(state.route===route)render();}
function bind(){document.querySelectorAll('[data-report-mode]').forEach(b=>b.addEventListener('click',()=>{state.reportMode=b.dataset.reportMode;render();}));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.action;if(k==='pdf')exportPdf();if(k==='allcases')navigate('cases');if(k==='ai')navigate('ai');if(k==='evidence')exportCsv(state.analysis.suspect);}));document.querySelectorAll('[data-case]').forEach(b=>{b.addEventListener('click',()=>showCase(b.dataset.case));b.addEventListener('keydown',e=>{if(e.key==='Enter')showCase(b.dataset.case);});});document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>{state.caseLevel=b.dataset.level;navigate('cases');}));document.querySelectorAll('[data-hour]').forEach(b=>b.addEventListener('click',()=>{state.hour=b.dataset.hour;state.page=0;navigate('logs');}));$('#case-level')?.addEventListener('change',e=>{state.caseLevel=e.target.value;render();});$('#log-search')?.addEventListener('input',e=>{state.query=e.target.value;state.page=0;const start=e.target.selectionStart;render();$('#log-search').focus();$('#log-search').setSelectionRange(start,start);});$('#only-linked')?.addEventListener('change',e=>{state.onlyLinked=e.target.checked;state.page=0;render();});$('#log-level')?.addEventListener('change',e=>{state.logLevel=e.target.value;state.page=0;render();});$('#prev')?.addEventListener('click',()=>{state.page--;render();});$('#next')?.addEventListener('click',()=>{state.page++;render();});$('#clear-hour')?.addEventListener('click',()=>{state.hour='';render();});$('#csv')?.addEventListener('click',()=>{const a=state.analysis,q=state.query.toLowerCase();exportCsv(a.rows.filter(r=>(!q||required.some(k=>String(r[k]).toLowerCase().includes(q)))&&(!state.onlyLinked||a.eventCases.has(r._key))&&(!state.hour||String(r.Timestamp).startsWith(state.hour))&&(!state.logLevel||(a.eventCases.get(r._key)||[]).some(c=>c.severity===state.logLevel))));});$('#author')?.addEventListener('input',e=>state.author=e.target.value);$('#report-date')?.addEventListener('change',e=>state.date=e.target.value);$('#load-ai')?.addEventListener('click',loadAi);$('#generate-ai')?.addEventListener('click',generateAi);$('#ai-context')?.addEventListener('change',e=>{state.aiSelection=e.target.value;resetAiOutput();render();});$('#ai-edit')?.addEventListener('input',e=>{state.aiText=e.target.value;state.aiApproved=false;$('#approve-ai').checked=false;});$('#approve-ai')?.addEventListener('change',e=>state.aiApproved=e.target.checked);$('#cancel-ai')?.addEventListener('click',()=>{state.worker?.terminate();state.worker=null;state.aiReady=false;state.aiBusy=false;state.aiStatus='Proceso cancelado. El análisis y el PDF siguen disponibles.';render();});}
function showCase(id){const c=state.analysis.cases.find(c=>c.id===id);if(!c)return;$('#detail-content').innerHTML=`<div class="detail-header"><div class="eyebrow">${c.id} · ${esc(c.type)}</div><h2>${esc(c.title)}</h2>${pill(c.severity)} <span class="pill neutral">Incidente probable</span><p>${esc(c.summary)}</p><div class="detail-metadata">${esc(c.start)} — ${esc(c.end)} · ${c.evidence.length} eventos<br>Activos: ${esc(c.hosts.join(', '))}<br>Cuentas: ${esc(c.users.join(', '))}</div></div><div class="detail-grid"><div><h3>Explicación técnica</h3><p>${esc(c.explanation)}</p><h3>Impacto posible</h3><p>${esc(c.impact)}</p><h3>Límites de la conclusión</h3><p>${esc(c.limit)}</p></div><div><h3>Justificación de criticidad</h3><p>${esc(c.justification)}</p><h3>Investigar</h3><ul class="plain-list">${c.investigate.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Contener</h3><ul class="plain-list">${c.contain.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Remediar</h3><ul class="plain-list">${c.remediate.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="chips">${c.techniques.map(t=>`<a class="pill neutral" href="https://attack.mitre.org/techniques/${t.replace('.','/').replace('T','T')}/" target="_blank" rel="noreferrer">${t}</a>`).join('')}</div><p class="tiny">Correspondencias ATT&CK propuestas, sujetas a validación.</p></div></div><h3>Evidencia completa del caso</h3><p class="tiny muted">Referencia directa a la hoja y fila original. Todos los comandos se muestran como texto.</p>${rawTable(c.evidence,true)}`;$('#detail-dialog').showModal();}
function exportPdf(){
 if(!state.analysis)return;
 try{
  const mode=state.reportMode,definition=REPORT_MODES[mode];
  const d=createPdf(state.analysis,window.jspdf.jsPDF,{mode,author:state.author,date:state.date,aiText:state.aiText,aiApproved:state.aiApproved});
  d.save(definition.fileName);
  notice(`${definition.label} generado. Archivo: ${definition.fileName}`);
 }catch(e){notice(`No se pudo generar el PDF: ${e.message}`,true);}
}
function exportCsv(rows){const headers=[...required,'Hoja_origen','Fila_origen','Caso','Criticidad_analitica'];const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return `"${s.replace(/"/g,'""')}"`;};const lines=[headers.map(safe).join(','),...rows.map(r=>{const cc=state.analysis.eventCases.get(r._key)||[];return [...required.map(k=>r[k]),r.sourceSheet,r.sourceRow,cc.map(c=>c.id).join('; '),cc.map(c=>c.severity).join('; ')].map(safe).join(',');})];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Evidencias_SOC.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function loadAi(){if(state.aiBusy)return;state.aiBusy=true;state.aiStatus='Iniciando descarga del modelo local…';state.aiProgress=0;render();state.worker=new Worker(new URL('./ai-worker.mjs',import.meta.url),{type:'module'});state.worker.onerror=e=>{state.aiBusy=false;state.aiReady=false;state.aiStatus='No se pudo iniciar la IA local. '+(e.message||'Revisa la conexión y vuelve a intentar.');notice(state.aiStatus,true);render();};state.worker.onmessage=({data})=>{if(data.type==='progress'){state.aiProgress=Math.round(data.progress||0);state.aiStatus=`Descargando ${data.file}: ${state.aiProgress}%`;if($('#ai-progress'))$('#ai-progress').style.width=state.aiProgress+'%';if($('#ai-status'))$('#ai-status').textContent=state.aiStatus;return;}if(data.type==='status'){state.aiStatus=data.text;if($('#ai-status'))$('#ai-status').textContent=data.text;return;}if(data.type==='ready'){state.aiBusy=false;state.aiReady=true;state.aiProgress=100;state.aiDevice=data.engine.toUpperCase();state.aiStatus='Modelo preparado. Puedes redactar sin claves API.';render();}if(data.type==='result'){state.aiBusy=false;state.aiApproved=false;try{if(state.aiRequest?.hash!==state.hash||state.aiRequest?.sheet!==state.analysis.meta.sheet||state.aiRequest?.selection!==state.aiSelection)throw new Error('El archivo o contexto cambió. Genera un nuevo resumen.');state.aiText=composeDraft(state.analysis,state.aiSelection,data.text);state.aiStatus='Resumen compuesto con extractos verificados. Puedes editarlo y revisarlo.';}catch(error){state.aiText='';state.aiStatus=error.message;notice(error.message,true);}render();}if(data.type==='error'){state.aiBusy=false;state.aiStatus=`Error de IA local: ${data.text}`;notice(state.aiStatus,true);render();}};state.worker.postMessage({type:'load'});}
function generateAi(){if(!state.aiReady||state.aiBusy)return;state.aiBusy=true;state.aiApproved=false;state.aiStatus="Redactando en el equipo… Esto puede tardar en CPU.";render();state.aiRequest={hash:state.hash,sheet:state.analysis.meta.sheet,selection:state.aiSelection};state.worker.postMessage({type:"generate",messages:aiMessages(state.analysis,state.aiSelection)});}
$('#export-top').addEventListener('click',()=>{navigate('report');notice('Elige informe ejecutivo, detallado o completo y descarga el PDF correspondiente.');});$('#close-detail').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});$('#help').addEventListener('click',()=>{notice('1. Carga el Excel. 2. Revisa incidentes y filas de evidencia. 3. Activa IA local y revisa su borrador. 4. Descarga el informe ejecutivo y el detallado desde Informes.');});window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render();});render();
